use strict;
use warnings;

# For selected symbols, count unique enclosing functions (fan-in as callers)
# Scan files and track current func as we go.

my @files;
open my $find, "find /bench/repo -name \"*.go\" ! -path \"*/web/*\" ! -path \"*/.git/*\" ! -path \"*/proto/gen/*\" |" or die;
while (<$find>) { chomp; push @files, $_; }
close $find;

my %targets = (
  "CompileToStatement" => qr/\.CompileToStatement\s*\(/,
  "NewEngine" => qr/(?<![.\w])NewEngine\s*\(/,
  "NewSchema" => qr/(?<![.\w])NewSchema\s*\(/,
  "GenUUID" => qr/\.GenUUID\s*\(/,
  "addArg" => qr/\.addArg\s*\(/,
  "jsonArrayExpr" => qr/(?<![.\w])jsonArrayExpr\s*\(/,
  "schemaField" => qr/schema\.Field\s*\(/,
  "renderChildren" => qr/\.renderChildren\s*\(/,
  "DefaultEngine" => qr/(?<![.\w])DefaultEngine\s*\(/,
  "AppendConditions" => qr/(?<![.\w]|filter\.)AppendConditions\s*\(|filter\.AppendConditions\s*\(/,
  "NewService" => qr/markdown\.NewService\s*\(|(?<![.\w])NewService\s*\(/,
);

my %callers; # symbol => { caller => count }
my %sites;
my %prod_callers;
my %prod_sites;

for my $p (@files) {
  open my $fh, "<", $p or die;
  my $cur = "<pkg>";
  my $is_test = ($p =~ /_test\.go$/);
  my $line = 0;
  while (<$fh>) {
    $line++;
    if (/^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z0-9_]+)\s*\(/) {
      my ($recv, $name) = ($1 // "", $2);
      my $rt = "";
      if ($recv ne "") { my @p = split /\s+/, $recv; $rt = $p[-1]; $rt =~ s/^\*//; }
      $cur = $rt ? "$rt.$name" : $name;
      next;
    }
    for my $sym (keys %targets) {
      if ($_ =~ $targets{$sym}) {
        # skip declaration lines
        next if /^func /;
        my $caller = "$p:$cur";
        $callers{$sym}{$caller}++;
        $sites{$sym}++;
        unless ($is_test) {
          $prod_callers{$sym}{$caller}++;
          $prod_sites{$sym}++;
        }
      }
    }
  }
}

print sprintf("%-20s %6s %7s %7s %8s\n", "symbol", "sites", "callers", "psites", "pcallers");
for my $sym (sort { ($sites{$b}//0) <=> ($sites{$a}//0) } keys %targets) {
  my $nc = scalar keys %{$callers{$sym}||{}};
  my $npc = scalar keys %{$prod_callers{$sym}||{}};
  printf "%-20s %6d %7d %7d %8d\n", $sym, $sites{$sym}//0, $nc, $prod_sites{$sym}//0, $npc;
  print "  callers:\n";
  for my $c (sort keys %{$callers{$sym}}) {
    print "    $c ($callers{$sym}{$c})\n";
  }
}
'
